    event_type: str
    order_id: str
    sku: str
    quantity: int
    payload: dict[str, Any]


class EventBus:
    def __init__(self) -> None:
        self._events: list[InventoryEvent] = []
        self._lock = Lock()

    def emit(
        self,
        *,
        event_type: str,
        order_id: str,
        sku: str,
        quantity: int,
        payload: dict[str, Any] | None = None,
    ) -> None:
        event = InventoryEvent(
            event_type=event_type.strip() or "unknown",
            order_id=order_id.strip(),
            sku=sku.strip(),
            quantity=quantity,
            payload=dict(payload or {}),
        )
        with self._lock:
            self._events.append(event)

    def list_events(self) -> list[InventoryEvent]:
        with self._lock:
            return list(self._events)

    def clear(self) -> None:
        with self._lock:
            self._events.clear()

    def count(self) -> int:
        with self._lock:
            return len(self._events)

    def find_by_order(self, order_id: str) -> list[InventoryEvent]:
        oid = order_id.strip()
        if not oid:
            return []
        with self._lock:
            return [event for event in self._events if event.order_id == oid]

    def find_by_type(self, event_type: str) -> list[InventoryEvent]:
        target = event_type.strip()
        if not target:
            return []
        with self._lock:
            return [event for event in self._events if event.event_type == target]

    def export_summary(self) -> dict[str, int]:
        with self._lock:
            by_type: dict[str, int] = {}
            for event in self._events:
                by_type[event.event_type] = by_type.get(event.event_type, 0) + 1
        return by_type

