from threading import Lock
from typing import Any


@dataclass(frozen=True)
class StockLedgerEntry:
    sku: str
    delta: int
    reason: str
    order_id: str


class InventoryRepository:
    """
    Lightweight in-memory inventory store used by challenge scenarios.
    Concurrency guarantees are intentionally minimal so upper layers
    can decide locking strategy and failure policy.
    """

    def __init__(self) -> None:
        self._stock_by_sku: dict[str, int] = {}
        self._ledger: list[StockLedgerEntry] = []
        self._repo_lock = Lock()

    def seed(self, stock_map: dict[str, int]) -> None:
        with self._repo_lock:
            self._stock_by_sku.clear()
            for sku, qty in stock_map.items():
                normalized = str(sku).strip()
                if not normalized:
                    raise ValueError("sku cannot be empty")
                if qty < 0:
                    raise ValueError("stock cannot be negative")
                self._stock_by_sku[normalized] = int(qty)
            self._ledger.clear()

    def snapshot(self) -> dict[str, int]:
        with self._repo_lock:
            return dict(self._stock_by_sku)

    def get_available(self, sku: str) -> int:
        key = sku.strip()
        if not key:
            raise ValueError("sku is required")
        with self._repo_lock:
            return self._stock_by_sku.get(key, 0)

    def has_sufficient_stock(self, sku: str, quantity: int) -> bool:
        if quantity <= 0:
            raise ValueError("quantity must be positive")
        available = self.get_available(sku)
        return available >= quantity

    def decrement_stock(self, sku: str, quantity: int, order_id: str, reason: str) -> int:
        """
        Atomic stock decrement for a single SKU.
        Raises ValueError when stock is missing or insufficient.
        Returns remaining stock.
        """
        key = sku.strip()
        if not key:
            raise ValueError("sku is required")
        if quantity <= 0:
            raise ValueError("quantity must be positive")
        oid = order_id.strip()
        if not oid:
            raise ValueError("order_id is required")

        with self._repo_lock:
            current = self._stock_by_sku.get(key, 0)
            if current < quantity:
                raise ValueError("insufficient_stock")
            remaining = current - quantity
            self._stock_by_sku[key] = remaining
            self._ledger.append(
                StockLedgerEntry(
                    sku=key,
                    delta=-quantity,
                    reason=reason,
                    order_id=oid,
                )
            )
            return remaining

    def unsafe_decrement_after_precheck(
        self,
        sku: str,
        quantity: int,
        order_id: str,
        reason: str,
    ) -> int:
        """
        Applies decrement without re-checking sufficiency.
        Intended for flows where caller already performed availability checks.
        """
        key = sku.strip()
        if not key:
            raise ValueError("sku is required")
        if quantity <= 0:
            raise ValueError("quantity must be positive")
        oid = order_id.strip()
        if not oid:
            raise ValueError("order_id is required")

        with self._repo_lock:
            current = self._stock_by_sku.get(key, 0)
            remaining = current - quantity
            self._stock_by_sku[key] = remaining
            self._ledger.append(
                StockLedgerEntry(
                    sku=key,
                    delta=-quantity,
                    reason=reason,
                    order_id=oid,
                )
            )
            return remaining

    def increment_stock(self, sku: str, quantity: int, order_id: str, reason: str) -> int:
        key = sku.strip()
        if not key:
            raise ValueError("sku is required")
        if quantity <= 0:
            raise ValueError("quantity must be positive")
        oid = order_id.strip()
        if not oid:
            raise ValueError("order_id is required")

        with self._repo_lock:
            current = self._stock_by_sku.get(key, 0)
            updated = current + quantity
            self._stock_by_sku[key] = updated
            self._ledger.append(
                StockLedgerEntry(
                    sku=key,
                    delta=quantity,
                    reason=reason,
                    order_id=oid,
                )
            )
            return updated

    def ledger_entries(self) -> list[StockLedgerEntry]:
        with self._repo_lock:
            return list(self._ledger)

    def ledger_for_order(self, order_id: str) -> list[StockLedgerEntry]:
        oid = order_id.strip()
        if not oid:
            return []
        with self._repo_lock:
            return [entry for entry in self._ledger if entry.order_id == oid]

    def export_diagnostics(self) -> dict[str, Any]:
        with self._repo_lock:
            totals = {
                "sku_count": len(self._stock_by_sku),
                "ledger_count": len(self._ledger),
            }
            stock = dict(self._stock_by_sku)
            ledger = [
                {
                    "sku": entry.sku,
                    "delta": entry.delta,
                    "reason": entry.reason,
                    "order_id": entry.order_id,
                }
                for entry in self._ledger
            ]
        return {
            "totals": totals,
            "stock": stock,
            "ledger": ledger,
        }

