from __future__ import annotations

from contextlib import contextmanager
from threading import Lock
from typing import Iterator


class LockManager:
    """
    Keyed lock manager for guarding critical sections around shared resources.
    """

    def __init__(self) -> None:
        self._registry_guard = Lock()
        self._locks: dict[str, Lock] = {}

    def _get_or_create(self, key: str) -> Lock:
        with self._registry_guard:
            lock = self._locks.get(key)
            if lock is None:
                lock = Lock()
                self._locks[key] = lock
            return lock

    def acquire(self, key: str) -> Lock:
        normalized = key.strip()
        if not normalized:
            raise ValueError("lock key is required")
        lock = self._get_or_create(normalized)
        lock.acquire()
        return lock

    def release(self, key: str) -> None:
        normalized = key.strip()
        if not normalized:
            return
        with self._registry_guard:
            lock = self._locks.get(normalized)
        if lock is not None and lock.locked():
            lock.release()

    @contextmanager
    def hold(self, key: str) -> Iterator[None]:
        lock = self.acquire(key)
        try:
            yield
        finally:
            if lock.locked():
                lock.release()

    def hold_many(self, keys: list[str]) -> list[Lock]:
        normalized = sorted({key.strip() for key in keys if key.strip()})
        if not normalized:
            return []
        acquired: list[Lock] = []
        for key in normalized:
            lock = self._get_or_create(key)
            lock.acquire()
            acquired.append(lock)
        return acquired

    def release_many(self, locks: list[Lock]) -> None:
        for lock in reversed(locks):
            if lock.locked():
                lock.release()

    def lock_count(self) -> int:
        with self._registry_guard:
            return len(self._locks)

