            return 0
        with self._lock:
            return self._tags.get(metric, {}).get(tag_key, 0)

    def snapshot(self) -> dict[str, Any]:
        with self._lock:
            values = dict(self._values)
            tags = {metric: dict(tag_map) for metric, tag_map in self._tags.items()}
        return {"values": values, "tags": tags}

    def reset(self) -> None:
