from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any


@dataclass(frozen=True)
class OrderLine:
    sku: str
    quantity: int

    def validate(self) -> None:
        if not self.sku.strip():
            raise ValueError("sku is required")
        if self.quantity <= 0:
            raise ValueError("quantity must be positive")


@dataclass(frozen=True)
class CheckoutRequest:
    order_id: str
    customer_id: str
    lines: list[OrderLine]
    metadata: dict[str, Any] = field(default_factory=dict)

    def validate(self) -> None:
        if not self.order_id.strip():
            raise ValueError("order_id is required")
        if not self.customer_id.strip():
            raise ValueError("customer_id is required")
        if not self.lines:
            raise ValueError("at least one order line is required")
        for line in self.lines:
            line.validate()


@dataclass(frozen=True)
class ReservationRecord:
    reservation_id: str
    order_id: str
    sku: str
    quantity: int
    success: bool
    reason: str


@dataclass(frozen=True)
class CheckoutResult:
    ok: bool
    reason: str
    order_id: str
    reservations: list[ReservationRecord]
    snapshot: dict[str, int]


def request_from_payload(payload: dict[str, Any]) -> CheckoutRequest:
    order_id = str(payload.get("order_id", "")).strip()
    customer_id = str(payload.get("customer_id", "")).strip()
    lines_payload = payload.get("lines", [])
    if not isinstance(lines_payload, list):
        raise ValueError("lines must be a list")

    lines: list[OrderLine] = []
    for item in lines_payload:
        if not isinstance(item, dict):
            raise ValueError("line must be an object")
        sku = str(item.get("sku", "")).strip()
        quantity_raw = item.get("quantity", 0)
        if isinstance(quantity_raw, bool):
            raise ValueError("quantity must be an integer")
        quantity = int(quantity_raw)
        lines.append(OrderLine(sku=sku, quantity=quantity))

    metadata_raw = payload.get("metadata", {})
    if metadata_raw is None:
        metadata: dict[str, Any] = {}
    elif isinstance(metadata_raw, dict):
        metadata = dict(metadata_raw)
    else:
        raise ValueError("metadata must be an object")

    request = CheckoutRequest(
        order_id=order_id,
        customer_id=customer_id,
        lines=lines,
        metadata=metadata,
    )
    request.validate()
    return request

